                         * Outer wrapper controls only
                         * the overall piece size.
                         *
                         * The inner span keeps the
                         * existing hover animation.
                         */
                        <span
                          className="
                        pointer-events-none
                        relative
                        z-10
                        flex
                        h-full
                        w-full
                        items-center
                        justify-center
                      "
