                            transform: `scale(${pieceScale}) rotate(${pieceCounterRotation}deg)`,

                            transformOrigin: "center center",

                            transition: pieceTransition,

                            willChange: "transform",
                          }}
                        >
                          <span
                            className={`
                          pointer-events-none
                          relative
                          select-none

                          font-serif
                          text-[10cqw]
                          leading-none

                          transition-transform
                          duration-150

                          group-hover:scale-[1.06]

