                      <>
                        <span
                          className="
                          pointer-events-none
                          absolute
                          inset-0
                          z-[19]
                          bg-zinc-950/90
                          backdrop-blur-[1px]
                        "
                        />
                        <span
                          className="
                          pointer-events-none
                          absolute
                          left-1/2
                          top-1/2
                          z-[19]
                          -translate-x-1/2
                          -translate-y-1/2
                          text-lg
                          leading-none
                          text-zinc-600/70
