                      RANK COORDINATE
                      1 2 3 4 5 6 7 8
                     ========================= */}

                    {displayColumn === 0 && (
                      <span
                        style={{
                          opacity: orientationAnimating ? 0 : 1,

                          transition: "opacity 120ms ease",
                        }}
                        className={`
                        pointer-events-none
                        absolute
                        left-1.5
                        top-1
                        z-20
                        text-[clamp(8px,1vw,12px)]
                        font-black

                        ${isLight ? "text-[#66452f]/70" : "text-[#f1ddbe]/70"}
                      `}
                      >
                        {rank}
                      </span>
                    )}
                  </button>
                );
              }),
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

