                      label={t("Hidden")}
                      value={64 - visibleSquares.length}
                    />
                  </div>
                )}
                {statsTab === "battle" && (
                  <div className="mt-4 grid grid-cols-2 gap-2">
                    <StatCard label={t("Captures")} value={fogStats.captures} />
