}

function getCheckedKingSquare(
  chess: Chess,
  viewingSide: FogSide,
): Square | null {
  if (!chess.isCheck() || chess.turn() !== viewingSide) return null;
  const board = chess.board();
  for (let row = 0; row < 8; row += 1)
    for (let col = 0; col < 8; col += 1) {
      const piece = board[row][col];
      if (piece?.type === "k" && piece.color === viewingSide)
        return getSquareName(row, col);
    }
  return null;
}
function historyPieceSymbol(color: "w" | "b", type: string) {
  return color === "w"
    ? (whiteSymbols[type] ?? "")
    : (blackSymbols[type] ?? "");
}
function Panel({ children }: { children: ReactNode }) {
  useUiLanguage();
  return (
    <section className="rounded-3xl border border-white/10 bg-zinc-900/75 p-4 shadow-xl shadow-black/20">
      {children}
    </section>
  );
}
function PanelTitle({
  title,
  subtitle,
  compact = false,
}: {
  title: string;
  subtitle: string;
  compact?: boolean;
}) {
  useUiLanguage();
  return (
    <div className={compact ? "" : "mb-5"}>
      <h2 className="text-sm font-bold text-zinc-100">{ui(title)}</h2>
      <p className="mt-1.5 text-xs text-zinc-500">{ui(subtitle)}</p>
    </div>
  );
}
function FogControls({
  onUndo,
  onRestart,
  undoDisabled,
  randomStart,
  onRandomStartChange,
  startSelectionDisabled,
  t,
}: {
  onUndo: () => void;
  onRestart: () => void;
  undoDisabled: boolean;
  randomStart: boolean;
  onRandomStartChange: (value: boolean) => void;
  startSelectionDisabled: boolean;
  t: (key: string) => string;
}) {
  useUiLanguage();
  return (
    <div className="space-y-3">
      <div>
        <p className="mb-2 text-[10px] font-black uppercase tracking-wider text-zinc-500">
          {t("Starting Position")}
        </p>
        <div className="grid grid-cols-2 gap-2">
          <button
            type="button"
            onClick={() => onRandomStartChange(false)}
            disabled={startSelectionDisabled}
            className={`rounded-xl border px-3 py-2.5 text-sm font-bold transition disabled:cursor-not-allowed disabled:opacity-40 ${
              !randomStart
                ? "border-sky-400/30 bg-sky-400/10 text-sky-200"
                : "border-white/10 bg-white/5 text-zinc-400 hover:bg-white/[0.08]"
            }`}
          >
            ♜ {t("Standard Start")}
          </button>
          <button
            type="button"
            onClick={() => onRandomStartChange(true)}
            disabled={startSelectionDisabled}
            className={`rounded-xl border px-3 py-2.5 text-sm font-bold transition disabled:cursor-not-allowed disabled:opacity-40 ${
              randomStart
                ? "border-violet-400/30 bg-violet-400/10 text-violet-200"
                : "border-white/10 bg-white/5 text-zinc-400 hover:bg-white/[0.08]"
            }`}
          >
            🎲 {t("Random Start")}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-2">
        <button
          type="button"
          onClick={onUndo}
          disabled={undoDisabled}
          className="rounded-xl border border-white/10 bg-white/5 px-3 py-2.5 text-sm font-bold text-zinc-300 disabled:cursor-not-allowed disabled:border-white/5 disabled:bg-white/[0.02] disabled:text-zinc-600 disabled:opacity-50 disabled:hover:bg-white/[0.02]"
