      <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-rose-400/10 text-lg font-black text-rose-200">
        {icon}
      </span>

      <div>
        <p className="text-xs font-black text-zinc-200">{ui(title)}</p>

