              )}

              {promotionSquare && promotionFrom && !historyPreview && (
                <div className="mb-3 rounded-2xl border border-violet-400/20 bg-zinc-900/90 p-3 shadow-xl">
                  <PromotionBar onPromote={promotePawn} />
                </div>
