                        value={String(mutationStats.totalMutations)}
                        detail={`1 / ${MUTATION_INTERVAL_PLIES} ${t("plies")}`}
                      />

                      <StatCard
                        icon="⚡"
                        label={t("Chaos score")}
                        value={String(mutationStats.chaosScore)}
