        const isHovered = hovered === quadrant;

        const isLocked = locked === quadrant;

        return (
          <div
            key={key}
            className={`absolute ${position} -translate-x-1/2 -translate-y-1/2 rounded-lg border px-2 py-1 text-[10px] font-black transition ${
              active
