                  : isLocked
                    ? "border-zinc-500/20 bg-zinc-950/60 text-zinc-600"
                    : "border-violet-300/20 bg-zinc-950/45 text-violet-200"
                : "border-violet-300/10 bg-zinc-950/30 text-violet-300/45"
            }`}
          >
            {quadrant}
          </div>
        );
      })}
    </div>
  );
