                        className={`flex w-full items-center justify-between border-b border-white/5 px-3 py-2.5 text-left text-xs transition last:border-0 ${
                          historyPreviewPly === record.ply
                            ? "bg-pink-400/10 text-pink-200"
                            : "text-zinc-400 hover:bg-white/5"
                        }`}
                      >
                        <span className="text-zinc-600">
                          {record.moveNumber}
                          {record.color === "w" ? "." : "..."}
                        </span>

                        <span className="font-black">{record.san}</span>
                      </button>
                    ))
                  )}
                </div>
              </Panel>
            </div>
          </aside>

          <section className="mx-auto w-full max-w-[820px] min-w-0">
            {historyPreview && (
              <div className="mb-3 flex items-center justify-between rounded-xl border border-pink-400/20 bg-pink-400/[0.07] px-4 py-3">
                <div>
                  <p className="text-[9px] font-black uppercase tracking-widest text-pink-300">
                    {t("History Preview")}
                  </p>

                  <p className="mt-1 text-sm font-bold text-white">
                    {historyPreview.moveNumber}
                    {historyPreview.color === "w" ? "." : "..."}{" "}
