                  </p>
                </div>

                <button
                  type="button"
                  onClick={() => setHistoryPreviewPly(null)}
                  className="rounded-lg bg-white/10 px-3 py-2 text-xs font-bold text-zinc-200 hover:bg-white/20"
                >
                  {t("Back to live")}
                </button>
              </div>
