          strokeWidth="1.5"
          strokeLinecap="round"
        />
        <path
          d="M50 62 Q46 66 42 64"
          stroke="#6b2117"
          strokeWidth="1.5"
          fill="none"
          strokeLinecap="round"
        />
        <path
          d="M50 62 Q54 66 58 64"
          stroke="#6b2117"
          strokeWidth="1.5"
          fill="none"
          strokeLinecap="round"
        />

        {/* whiskers */}
